    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];

    // Thread / block indices
    mov.u32 %r1, %tid.x;        // threadIdx.x
    mov.u32 %r2, %ctaid.x;      // blockIdx.x (row index)

    // --------------------------------------------------------------------
    // Constants (hard‑coded for this model)
    // --------------------------------------------------------------------
    // ROW_SIZE   = 32768  elements per row
    // ROW_BYTES  = 65536  bytes per row (2 bytes per fp16)
    // SEG_ELEMS  = 32     elements processed per thread
    // SEG_BYTES  = 64     bytes per thread segment (32 * 2)
    // BLOCK_SZ   = 1024   threads per block
    // --------------------------------------------------------------------
    // Compute base addresses for this row
    mul.wide.u32   %rd3, %r2, 65536;   // row_offset_bytes
    add.u64        %rd4, %rd1, %rd3;   // input row base pointer
    add.u64        %rd5, %rd2, %rd3;   // output row base pointer

    // Compute per‑thread segment base pointers
    mul.wide.u32   %rd6, %r1, 64;      // thread_offset_bytes
    add.u64        %rd7, %rd4, %rd6;   // input segment base
    add.u64        %rd8, %rd5, %rd6;   // output segment base

    // --------------------------------------------------------------------
    // First pass: compute each thread's total product and store in shared
    // --------------------------------------------------------------------
    .shared .align 4 .f32 sdata[1024];   // one float per thread

    mov.f32 %f1, 1.0;                    // local product accumulator

    // Loop over 32 elements to compute total product
    mov.u32 %i, 0;
LOOP_TOTAL:
    setp.ge.u32 %p1, %i, 32;
    @%p1 bra END_LOOP_TOTAL;

    // Load fp16 element, convert to fp32, multiply
    mul.wide.u32 %addr, %i, 2;           // byte offset within segment
    add.u64 %addr, %rd7, %addr;          // address of element
    ld.global.f16 %h1, [%addr];
    cvt.rn.f32.f16 %f2, %h1;
    mul.f32 %f1, %f1, %f2;

    add.u32 %i, %i, 1;
    bra LOOP_TOTAL;
END_LOOP_TOTAL:

    // Store thread total product to shared memory
    st.shared.f32 [sdata + %r1*4], %f1;
    bar.sync 0;

    // --------------------------------------------------------------------
    // Inclusive scan (Hillis‑Steele) over thread totals
    // --------------------------------------------------------------------
    mov.u32 %r3, 1;          // offset = 1
SCAN_LOOP:
    setp.ge.u32 %p2, %r3, 1024;
    @%p2 bra SCAN_DONE;

