    ld.shared.f32 %f3, [sdata + %r1*4];
    // Load partner value if threadIdx >= offset
    mov.f32 %f4, 1.0;
    setp.ge.u32 %p3, %r1, %r3;
    @%p3 {
        ld.shared.f32 %f4, [sdata + (%r1 - %r3)*4];
    }
    // Multiply and store back
    mul.f32 %f3, %f3, %f4;
    st.shared.f32 [sdata + %r1*4], %f3;
    bar.sync 0;

    shl.b32 %r3, %r3, 1;     // offset <<= 1
    bra SCAN_LOOP;
SCAN_DONE:

