    // --------------------------------------------------------------------
    .reg .f32 %prefix;
    setp.eq.u32 %p4, %r1, 0;
    @%p4 mov.f32 %prefix, 1.0;
    @!%p4 {
        ld.shared.f32 %prefix, [sdata + (%r1 - 1)*4];
    }

    // --------------------------------------------------------------------
    // Second pass: write cumulative products using the prefix
    // --------------------------------------------------------------------
    mov.f32 %f5, %prefix;    // accumulator starts with exclusive prefix

    mov.u32 %i, 0;
WRITE_LOOP:
    setp.ge.u32 %p5, %i, 32;
    @%p5 bra END_WRITE_LOOP;

    // Load element again
    mul.wide.u32 %addr, %i, 2;
    add.u64 %addr, %rd7, %addr;
    ld.global.f16 %h2, [%addr];
    cvt.rn.f32.f16 %f6, %h2;
    mul.f32 %f5, %f5, %f6;               // update accumulator

    // Store accumulator as fp16
    cvt.rn.f16.f32 %h3, %f5;
    // Compute output address
    add.u64 %addr, %rd8, %addr;
    st.global.f16 [%addr], %h3;

    add.u32 %i, %i, 1;
    bra WRITE_LOOP;
END_WRITE_LOOP:

